#!/usr/bin/env python3
"""IL-27 scenarios (guided walkthroughs) and branchingScenarios (decision trees)."""
import json

SC = []
def scenario(id, moduleId, title, context, objectives, tasks):
    SC.append({"id": id, "moduleId": moduleId, "title": title, "context": context,
               "objectives": objectives, "tasks": tasks})

scenario("IL27-SCEN-01", "IL27-M03", "Morning after a promotion: validate the new DC",
    "You promoted LAB-DC01 to a domain controller last night. Before users arrive, run the full validation pass a real admin runs: replication, DNS, SYSVOL, and time sync.",
    ["Verify dcdiag is clean", "Confirm DNS and SYSVOL health", "Check time sync (Kerberos breaks past 5 minutes of skew)"],
    [
        {"task": "Run dcdiag /q and repadmin /replsummary", "guidance": "Quiet output is good output. Any error here stops the line — fix before users log on.", "verify": "dcdiag silent; repadmin shows 0 fails, largest delta under 60 minutes"},
        {"task": "Confirm the SYSVOL share and NETLOGON share exist", "guidance": "net share | findstr SYSVOL — if missing, run dcdiag /test:netlogons and check the DFSR event log.", "verify": "Both shares listed"},
        {"task": "Check time: w32tm /query /status", "guidance": "Stratum should be sane and offset small. Point the DC at a reliable NTP source: w32tm /config /manualpeerlist:\"time.windows.com\" /syncfromflags:manual /reliable:yes /update.", "verify": "Offset under 1 second; source is your configured peer"},
        {"task": "Create a test user and confirm replication attributes", "guidance": "New-ADUser -Name 'replication-test' ... then Get-ADUser replication-test -Server lab-dc01.lab.local — proves ADWS and the directory are serving.", "verify": "Test user retrievable immediately"},
    ])

scenario("IL27-SCEN-02", "IL27-M05", "The printer VLAN can't reach the print server",
    "Printers live on VLAN 30 (192.168.30.0/24); the print server is on the server segment. Jobs spool but never print. Find the layer at fault.",
    ["Map the path printer -> gateway -> firewall -> server", "Test each hop and each required port", "Fix the actual fault, not the symptom"],
    [
        {"task": "From a workstation on VLAN 30, ping the print server", "guidance": "If ping fails, it is routing/firewall. If ping works but printing fails, it is ports or the spooler.", "verify": "Ping result recorded either way"},
        {"task": "Test-NetConnection print-srv -Port 445 and -Port 9100", "guidance": "445 = SMB (driver/share access), 9100 = raw printing. Note which passes.", "verify": "Port test results for both ports recorded"},
        {"task": "Check the pfSense rule between VLAN 30 and the server segment", "guidance": "Firewall > Rules > VLAN30: you need pass rules for TCP 445, 139, 9100, 515 from the printer subnet to the print server IP.", "verify": "Rules present and logged as passing (check the firewall log)"},
        {"task": "Confirm the printer's gateway and DNS", "guidance": "Printers with wrong gateways are a classic: print the config page and verify gateway = the VLAN 30 interface.", "verify": "Printer config page shows correct gateway"},
    ])

scenario("IL27-SCEN-03", "IL27-M11", "Alert storm: 40 hosts report 'unreachable' at once",
    "Zabbix fires 40 host-down alerts within two minutes at 9:04 AM. Forty hosts do not die at once — something shared broke. Triage like an on-call engineer.",
    ["Resist the urge to touch hosts; find the common dependency", "Confirm with one targeted test", "Resolve and tune the alert so it doesn't page 40 times next time"],
    [
        {"task": "List the 40 hosts: do they share a switch, a hypervisor host, or a network segment?", "guidance": "Monitoring > Problems > filter by time; export the host list and compare subnets. Shared fate = shared cause.", "verify": "Common factor identified (e.g. all on Hyper-V host HV-02, or all behind switch SW-3)"},
        {"task": "Check the infrastructure ABOVE the hosts: hypervisor host status, switch uplinks, the Zabbix proxy if one is in path", "guidance": "One ping to the hypervisor host tells you more than 40 host checks.", "verify": "Root device identified (e.g. HV-02 unreachable)"},
        {"task": "Fix the root (reboot hung host, reseat uplink, etc.) and watch recovery cascade", "guidance": "Fix one thing, watch the Problems dashboard clear top-down.", "verify": "All 40 clear without per-host intervention"},
        {"task": "Add dependency-aware alerting so next time you get ONE alert", "guidance": "Zabbix: set the hypervisor/switch as the hosts' 'proxy' parent or use trigger dependencies — child alerts suppressed when the parent is down.", "verify": "Dependency configured; document it in the runbook"},
    ])

scenario("IL27-SCEN-04", "IL27-M12", "Restore the finance share from last night's backup",
    "Finance deleted the Q3 folder from \\\\lab-fs01\\departments at 10 AM. The nightly backup ran at 2 AM. Restore it — and prove nothing else changed.",
    ["Identify the correct backup version", "Restore to an alternate location first (never overwrite live data blindly)", "Verify integrity, then put it back"],
    [
        {"task": "wbadmin get versions — pick last night's 02:00 version identifier", "guidance": "Match the version timestamp to before the 10 AM deletion.", "verify": "Version identifier copied"},
        {"task": "Recover to C:\\RestoreStaging: wbadmin start recovery -version:<id> -itemType:File -items:D:\\Shares\\Departments\\Finance\\Q3 -recoveryTarget:C:\\RestoreStaging -quiet", "guidance": "Alternate location first — if the backup is corrupt you haven't touched the live share.", "verify": "Q3 folder present under C:\\RestoreStaging"},
        {"task": "Verify: count files, spot-open the largest spreadsheet, compare against the finance lead's expectation", "guidance": "A restore you don't verify is a rumor. Check counts and open the critical files.", "verify": "File count matches; spot checks open cleanly"},
        {"task": "Copy back to the live share with robocopy /MIR from staging, preserving timestamps", "guidance": "robocopy C:\\RestoreStaging\\Q3 D:\\Shares\\Departments\\Finance\\Q3 /MIR /COPY:DAT — then confirm NTFS permissions inherited correctly.", "verify": "Live share restored; permissions correct; user confirms"},
    ])

scenario("IL27-SCEN-05", "IL27-M08", "lab-linux01 won't take SSH after a reboot",
    "The Ubuntu box rebooted overnight for updates. Now SSH times out. The services depend on it. Work the console-first recovery flow.",
    ["Get in via the hypervisor console", "Determine whether it's network, SSH daemon, or firewall", "Fix and add a guard so it doesn't recur silently"],
    [
        {"task": "Open the hypervisor console and log in locally", "guidance": "When SSH is dead, the console is your crash cart. Confirm the OS actually booted.", "verify": "Local login works; uptime shows recent boot"},
        {"task": "systemctl status ssh; ss -tlnp | grep :22", "guidance": "Is sshd running AND listening? Distinguish 'dead daemon' from 'blocked port'.", "verify": "sshd state and listener status recorded"},
        {"task": "ip addr; ip route; ping 192.168.10.1", "guidance": "No IP = netplan/DHCP issue; IP but no gateway ping = vSwitch/VLAN issue.", "verify": "Network layer verdict recorded"},
        {"task": "Fix the found cause (e.g. netplan yaml broken by update: fix indentation, netplan apply; or ufw re-enabled with wrong rules)", "guidance": "Fix one layer, re-test SSH from your workstation after each change.", "verify": "SSH works from workstation"},
        {"task": "Add a Zabbix agent check on TCP 22 and an 'unreachable' trigger", "guidance": "You should have been paged before the ticket. Close that gap now.", "verify": "Trigger exists and is tested"},
    ])

scenario("IL27-SCEN-06", "IL27-M16", "New-hire onboarding day (the full loop)",
    "It's Monday 8 AM. Three new hires start in the IT department. Run the complete onboarding loop: account, hardware, access, orientation — and document everything for the audit trail.",
    ["Provision identity before hardware", "Apply least-privilege access", "Leave a paper trail the auditors will love"],
    [
        {"task": "Create the three AD accounts in OU=Users with the bulk script (IL27-TERM-01 pattern), temp passwords, change-at-logon", "guidance": "Script it — Monday-morning clicking is how typos become security incidents.", "verify": "3 accounts exist, enabled, in correct OU, password-change flagged"},
        {"task": "Add to groups: LAB-IT for all three; no Domain Admins, no exceptions — document any extra access as a ticket", "guidance": "Least privilege on day one. Elevated access goes through the access-request process, not onboarding.", "verify": "Group memberships match the access matrix; ticket numbers recorded"},
        {"task": "Image or configure laptops: join to lab.local, confirm GPOs apply (gpresult), verify Defender + BitLocker status", "guidance": "A laptop that skipped the baseline GPO is a rogue device with a welcome mat.", "verify": "gpresult shows baseline GPOs; BitLocker encrypting; Defender real-time on"},
        {"task": "Orientation checklist: acceptable-use policy signed, phishing briefing done, MFA enrolled, manager intro", "guidance": "The human controls matter as much as the technical ones — log each with date/time.", "verify": "Signed checklist filed per hire"},
        {"task": "Offboarding rehearsal: disable (don't delete) one test account and confirm its access dies", "guidance": "Disable-ADAccount testuser; verify login fails and group memberships remain for audit. Deletion destroys the audit trail — disable first, delete per retention policy.", "verify": "Test account cannot authenticate; audit log shows the disable event"},
    ])

# ---------------- Branching scenarios ----------------
BR = []
def branch(id, moduleId, title, start, nodes):
    BR.append({"id": id, "moduleId": moduleId, "title": title, "start": start, "nodes": nodes})

def N(text, choices, explanation=None):
    n = {"text": text, "choices": choices}
    if explanation: n["explanation"] = explanation
    return n

def C(label, next, feedback):
    return {"label": label, "next": next, "feedback": feedback}

branch("IL27-BRANCH-01", "IL27-M03", "Domain controller won't boot",
    "dc_down",
    {
        "dc_down": N("Monday 7:55 AM. LAB-DC01 won't boot — it hangs at the Windows logo with spinning dots. Users arrive in 5 minutes and nothing authenticates without the DC. What's your FIRST move?",
            [C("Boot into Directory Services Restore Mode and seize roles", "dsrm_panic", "Too drastic for step one — you don't even know what's wrong yet, and seizing roles on a sick DC can corrupt AD."),
             C("Check the hypervisor console for the actual error / boot into Safe Mode to observe", "observe", "Correct instinct: diagnose before you treat. The console often shows the real error (disk, update, driver)."),
             C("Restore the whole VM from last night's backup immediately", "restore_now", "Restore is a valid card, but playing it before a 2-minute diagnosis wastes your fastest recovery path if it's something trivial."),
             C("Tell users to work offline until IT figures it out", "give_up", "Giving up before diagnosing is never the first move — and cached credentials only go so far.")]),
        "observe": N("Safe Mode shows: 'We couldn't complete the updates. Undoing changes.' A Windows Update wedged the boot. Users are arriving. Now what?",
            [C("Let it finish undoing changes — monitor, and prep the backup restore in parallel", "patient", "Right call: the undo usually completes in 10-20 minutes. Prepping the restore in parallel means you're covered either way."),
             C("Hard-power-off the VM mid-undo to speed things up", "powerkill", "Never interrupt 'undoing changes' — you'll convert a slow boot into a corrupted component store."),
             C("Boot DSRM and restore System State from backup", "dsrm_restore", "Premature: DSRM restore is for AD corruption, not a wedged update. Let the rollback finish first.")]),
        "patient": N("The undo finished — LAB-DC01 booted cleanly at 8:20. dcdiag is clean. What's the correct follow-through?",
            [C("Document the incident, pause automatic updates on DCs, schedule updates in a maintenance window", "done_right", "Correct: DCs get updates on YOUR schedule with a tested rollback plan, never auto-install at 3 AM before a workday."),
             C("Do nothing — it's working now", "done_wrong", "The same update will wedge it again next cycle. 'Working now' without a preventive change is just scheduling the next outage."),
             C("Reinstall the server from scratch to be safe", "overkill", "The system is healthy and dcdiag is clean — a rebuild burns hours for zero gain and risks new mistakes.")],
            explanation="Correct path: observe first (Safe Mode diagnosis), let the update rollback complete while prepping restore in parallel, then prevent recurrence with a DC maintenance-window policy. The discipline is: diagnose, protect your options, fix, then make it not happen again."),
        "dsrm_panic": N("You seized roles in DSRM on a DC whose database may be fine. Replication partners now see conflicting role holders. What did this cost you?",
            [C("A metadata cleanup and possible USN rollback risk — seizing without diagnosing was the error", "lesson", "Exactly. Role seizure is for a DEAD DC, not a sick one. Now you own a cleanup.")],
            explanation="Role seizure is a last resort for a permanently dead DC. Doing it on a recoverable DC creates more damage than the original fault."),
        "restore_now": N("The restore is running — 45 minutes. Meanwhile a colleague checks the console: it was just 'undoing changes' and would have finished in 15 minutes. Lesson?",
            [C("Diagnose for 2 minutes before committing to the 45-minute path", "lesson", "Right. The restore wasn't wrong, just premature — a 2-minute console check would have picked the faster path.")],
            explanation="Restores are powerful but slow. A quick diagnosis first lets you choose the fastest correct recovery."),
        "give_up": N("By 9:30 users can't reach file shares (Kerberos needs the DC) and you're still 'figuring it out.' What should step one have been?",
            [C("Console diagnosis — the 2-minute check that drives every later decision", "lesson", "Yes. Every incident starts with facts, not announcements.")],
            explanation="Communicate status AND diagnose in parallel — but never substitute announcements for diagnosis."),
        "powerkill": N("The VM now blue-screens with INACCESSIBLE_BOOT_DEVICE. The component store is corrupted. Your options narrowed to one:",
            [C("Restore from last night's backup (the path you should have prepped, not interrupted)", "lesson", "Correct — and now it's the ONLY path, plus you lost the 15-minute natural recovery.")],
            explanation="Interrupting a Windows rollback corrupts the component store. Patience during 'undoing changes' is a technical requirement, not a virtue."),
        "dsrm_restore": N("DSRM System State restore on a merely update-wedged DC: it works, but took 90 minutes and forced a non-authoritative dance. The faster path was:",
            [C("Letting the rollback finish (~15 min) — match the tool to the diagnosis", "lesson", "Right tool, wrong incident. Diagnosis drives tool selection.")],
            explanation="System State restore is for AD corruption. A wedged update just needs its rollback to complete."),
        "done_right": N("Incident closed: 25-minute outage, root cause documented, DCs moved to a Sunday 2 AM maintenance window with snapshots. The review board asks what you'll do differently. Answer:",
            [C("Nothing about the response — but updates now go to a canary member server first, then DCs", "end", "Mature answer: the response was sound; you're adding a canary tier so DCs never take an untested update.")],
            explanation="Correct-path explanation: diagnose (console/Safe Mode) → protect options (prep restore in parallel) → let the safe path play out → prevent recurrence (maintenance windows + canary tier). Total: 25 minutes, one lesson institutionalized."),
        "done_wrong": N("Three weeks later the same update wedges the DC again — this time during payroll processing. The post-mortem writes itself.",
            [C("Restart the scenario with the maintenance-window lesson applied", "dc_down", "Good — run it again and pick the preventive path this time.")],
            explanation="Unfixed root causes recur at the worst possible time. The follow-through IS the fix."),
        "overkill": N("Six hours into a rebuild, you realize the original system was healthy. The business lost a day for nothing.",
            [C("Restart and trust the diagnostics when they're clean", "dc_down", "dcdiag clean + successful boot = healthy. Don't rebuild healthy systems.")],
            explanation="Rebuilding a verified-healthy system is the most expensive form of anxiety."),
        "lesson": N("Lesson logged. The core discipline this scenario teaches:",
            [C("Return to start and run the correct path", "dc_down", "Diagnose first, protect options, match the tool to the fault, then prevent recurrence.")],
            explanation="Diagnose → options → correct tool → prevention. That's the whole incident-response loop in one scenario."),
        "end": N("Scenario complete. You handled a down DC in 25 minutes and left the environment better than you found it. That's the job.",
            [C("Next scenario", "dc_down", "Loop back and try a different first move to see the consequences.")],
            explanation="Mastery = correct path under time pressure, plus institutional learning."),
    })

branch("IL27-BRANCH-02", "IL27-M05", "DNS is down for the whole office",
    "dns_down",
    {
        "dns_down": N("9:12 AM: tickets flood in — 'internet is down,' 'can't reach anything.' You test: ping 8.8.8.8 works, but no name resolves anywhere. DNS is down office-wide. First action?",
            [C("Check whether the DNS Server service is running on LAB-DC01", "check_service", "Yes — start with the service that owns the symptom. One command, thirty seconds."),
             C("Reboot LAB-DC01 immediately", "reboot_dc", "Rebooting the DC is the nuclear option as step one — it kills auth for everyone and you still won't know the cause."),
             C("Tell users to use 8.8.8.8 as a workaround", "workaround", "That bypasses internal DNS entirely — lab.local stops resolving and AD breaks. Workarounds must not break identity."),
             C("Assume the ISP is down and call them", "blame_isp", "Ping 8.8.8.8 works — the ISP is fine. The evidence already rules this out; read it.")]),
        "check_service": N("Get-Service DNS on LAB-DC01: Status = Stopped. It stopped at 9:04 AM. What next?",
            [C("Start the service, then immediately check WHY it stopped (event log)", "start_and_why", "Correct: restore service first (users are down), then find the cause before it recurs."),
             C("Start the service and walk away", "start_only", "Service is up — but if you don't learn why it stopped, you'll be back here tomorrow."),
             C("Set it to Automatic and reboot the server", "auto_reboot", "It was already Automatic — that's why it tried to start at boot. The setting isn't the problem.")]),
        "start_and_why": N("DNS is running again — tickets stop. Event log shows: Event 769, 'The DNS server is out of memory' — wait, no: Event 150, 'could not open socket for 192.168.20.10.' Something else grabbed port 53. Suspects?",
            [C("Check for a second DNS/DHCP service or a container bound to port 53", "port_conflict", "Right instinct: port conflicts are the #1 'DNS just stopped' cause on lab servers."),
             C("Add more RAM to the DC", "more_ram", "Event 150 is a socket bind failure, not memory pressure. Treat the actual error, not a guess."),
             C("Reinstall the DNS role", "reinstall", "The role is fine — something is squatting on its port. Reinstalling changes nothing.")]),
        "port_conflict": N("netstat -ano | findstr :53 shows PID 2144 listening on 0.0.0.0:53. Tasklist: it's a Docker proxy from a Pi-hole test container someone left running on the DC. Resolution?",
            [C("Stop/remove the rogue container, restart DNS, document 'no test containers on DCs' as policy", "done_right", "Correct: remove the squatter, restore the service, and make the rule explicit so it sticks."),
             C("Just kill the PID", "kill_pid", "The container restarts on reboot (restart policy) — killing the process is whack-a-mole."),
             C("Move DNS to a different port", "move_port", "DNS must be on 53 — every client on earth expects it there. Move the squatter, never the service.")],
            explanation="Correct path: verify the service → restore it → read the actual event → find the port squatter → remove it permanently → policy. Total downtime ~10 minutes, and the 'no test workloads on DCs' rule prevents the sequel."),
        "start_only": N("Next morning, 9:04 AM again: DNS stopped again. The squatter container restarted with the DC. Now you do the full job:",
            [C("Remove the container and write the policy", "done_right", "Now you've paid the tuition — make the lesson permanent.")],
            explanation="Uninvestigated root causes recur on a schedule. The second outage is the one you chose."),
        "reboot_dc": N("The DC reboots — 8 minutes of zero authentication, file shares drop, and DNS is STILL stopped because the squatter container auto-started again. What did the reboot buy?",
            [C("Nothing but an 8-minute full outage — diagnose before rebooting", "dns_down", "Reboots feel decisive and teach you nothing. Check the service first.")],
            explanation="Rebooting without diagnosis converts a 2-minute fix into an 8-minute outage and leaves the cause running."),
        "workaround": N("Users set 8.8.8.8 manually. Now group policy fails, file shares prompt for passwords, and 'lab.local' doesn't resolve. The helpdesk queue doubled. Revert and:",
            [C("Go back and check the DNS service properly", "dns_down", "Workarounds that break identity are worse than the outage.")],
            explanation="External DNS as a workaround breaks AD. Never bypass internal DNS on domain members."),
        "blame_isp": N("ISP support: 'our network is fine, and your pings prove it.' Twenty minutes lost. The evidence (ping works, names fail) always pointed at:",
            [C("Local DNS — back to the DC and check the service", "dns_down", "Read the evidence: IP works + names fail = DNS, and it's YOUR DNS.")],
            explanation="IP-reachable but name-unresolvable is never the ISP. It's your resolver chain."),
        "more_ram": N("You added RAM. DNS still can't bind port 53. The event log still says socket failure. Treat the:",
            [C("Actual error: find what's on port 53", "port_conflict", "Always treat the logged error, not the guessed cause.")],
            explanation="Event 150 names the problem: something holds the socket. Find it."),
        "reinstall": N("After a 30-minute role reinstall, DNS starts — then stops again at the next reboot when the container returns. The role was never broken:",
            [C("Find the port squatter instead", "port_conflict", "Reinstalling a healthy role to fix a port conflict is surgery for a splinter.")],
            explanation="If a reinstall 'fixes' it temporarily, the cause is environmental, not the role."),
        "kill_pid": N("PID killed — DNS starts. After the next reboot, the container (restart: always) grabs port 53 again. Permanent fix:",
            [C("Remove the container / its restart policy", "done_right", "Processes come back; configurations persist. Fix the configuration.")],
            explanation="Kill the process AND its resurrection mechanism."),
        "move_port": N("You moved DNS to 5353. Zero clients can resolve anything — DNS on a nonstandard port might as well not exist. Undo and:",
            [C("Remove the squatter; DNS stays on 53", "done_right", "Infrastructure services live on their standard ports. Full stop.")],
            explanation="Standard ports are a contract with every client. Never move the service; move the squatter."),
        "done_right": N("DNS stable for a week. Your runbook now has: 'DNS down → Get-Service DNS → event log → netstat :53 → no test workloads on DCs.' The review board is happy. Close it:",
            [C("Close the incident with the runbook update attached", "end", "An incident isn't closed when service restores — it's closed when the runbook learns.")],
            explanation="Correct-path explanation: service check → restore → actual error → port squatter → permanent removal → policy + runbook. Ten minutes of downtime, zero recurrences."),
        "auto_reboot": N("It WAS already Automatic — the service tried and failed to start because port 53 is taken. The setting was never the problem. Check:",
            [C("What's actually on port 53", "port_conflict", "Settings don't fix conflicts. Evidence does.")],
            explanation="Verify assumptions: 'Automatic' doesn't help when the port is occupied."),
        "end": N("Scenario complete. Office-wide DNS outage resolved in ~10 minutes with a runbook update. That's infrastructure work.",
            [C("Next scenario", "dns_down", "Try the wrong first moves to feel their cost.")],
            explanation="Mastery = fastest correct path + the recurrence prevention."),
    })

branch("IL27-BRANCH-03", "IL27-M15", "Ransomware alert on an endpoint",
    "ransom_alert",
    {
        "ransom_alert": N("2:14 PM: Zabbix fires — LAB-W11-01 is renaming hundreds of files per minute, and a ransom note appeared on the desktop. This is the real thing (or the drill — treat it as real). FIRST action?",
            [C("Isolate the host from the network immediately (disable NIC / firewall-block its IP)", "isolate", "Correct: containment first. Every second online is more encrypted files and possible lateral movement."),
             C("Start deleting the encrypted files to clean up", "delete_files", "Deleting destroys evidence AND the only copies you might recover. Never delete during containment."),
             C("Pay the ransom to get the data back fast", "pay", "No — payment funds crime, often doesn't deliver a working key, and in the drill it's disallowed. Recovery comes from backups."),
             C("Shut the host down hard right now", "poweroff", "Tempting, but a hard shutdown loses RAM forensics and can corrupt the evidence snapshot. Isolate first, snapshot, then decide.")]),
        "isolate": N("Host isolated — NIC disabled at the hypervisor. File renaming stopped. Next, in order?",
            [C("Snapshot the VM for evidence, then identify patient zero (how did it get in?)", "evidence", "Right: preserve evidence BEFORE remediation. Snapshots are cheap; lost forensics are gone forever."),
             C("Immediately restore from backup", "restore_fast", "Restore without knowing the entry point = reinfection. Find patient zero first."),
             C("Re-enable the NIC briefly to 'check something'", "reconnect", "Reconnecting an infected host, even briefly, risks lateral movement. The one exception is a controlled forensic VLAN — not the production LAN.")]),
        "evidence": N("Snapshot taken. PowerShell history shows a malicious macro-enabled attachment opened at 1:58 PM; a scheduled task 'Updater' runs the payload hourly. Eradication plan?",
            [C("Delete the scheduled task, remove the payload + persistence, kill related processes — then verify no other persistence (registry Run keys, WMI)", "eradicate", "Correct and complete: kill ALL persistence mechanisms, not just the obvious one."),
             C("Just delete the ransom note", "note_only", "The note is a symptom. The scheduled task will re-encrypt everything within the hour."),
             C("Run a full antivirus scan and call it done", "av_only", "AV helps, but the scheduled task + registry persistence need manual removal and verification.")]),
        "eradicate": N("Persistence removed, processes dead, second scan clean. The user's Documents are encrypted (.locked). Recovery?",
            [C("Restore from last night's backup to an alternate location, verify, then return to the user — and check backup integrity for the whole share", "restore", "Correct: alternate-location restore, verify before touching live data, and confirm the backups themselves aren't compromised."),
             C("Try a free decryptor from the internet on the production files", "decryptor", "Decryptors work only for specific families and can corrupt files further. Verify the family first, test on COPIES."),
             C("Tell the user the files are gone", "giveup_data", "Not until you've checked the backups — that's literally what they're for.")],
            explanation="Correct path: isolate → snapshot/evidence → find entry point → eradicate ALL persistence → restore from verified backup → lessons learned. Speed matters, but order matters more."),
        "delete_files": N("You deleted encrypted files — including the ransom note with the incident ID and the originals you could have restored over. Forensics is now guesswork.",
            [C("Restart: isolate first, touch nothing", "ransom_alert", "Containment before cleanup. Always.")],
            explanation="During containment, every file is evidence. Deletion is a post-recovery, approved action."),
        "pay": N("Payment sent. No key arrived — and the incident is now a legal/compliance event too. The correct recovery was always:",
            [C("Isolate and restore from backup — restart the scenario", "ransom_alert", "Backups are the ransom you pay in advance, on your terms.")],
            explanation="Paying doesn't work reliably and creates new liability. Tested backups are the answer."),
        "poweroff": N("Hard shutdown done. RAM forensics lost; the disk snapshot may be crash-inconsistent. It works, but you paid a forensics tax. Better first move was:",
            [C("Network isolation (keeps the host alive for forensics)", "ransom_alert", "Isolation stops the bleeding without killing the patient.")],
            explanation="Isolate > power off: same containment, preserved forensics."),
        "restore_fast": N("Restored from backup — and the scheduled task you never found re-encrypted everything by 4 PM. The step you skipped:",
            [C("Patient-zero + persistence removal BEFORE restore", "ransom_alert", "Eradicate, then restore. Order is everything.")],
            explanation="Restoring onto a still-compromised host is just scheduling the second incident."),
        "reconnect": N("During the 90 seconds online, the payload scanned the subnet and hit the file server's SMB. You now have TWO incidents. The rule:",
            [C("Isolated means isolated — restart", "ransom_alert", "Never reconnect an infected host to production. Ever.")],
            explanation="One reconnection can double your incident. Containment is binary."),
        "note_only": N("One hour later the scheduled task fired and re-encrypted the restored files. You treated the symptom. Treat the:",
            [C("Persistence mechanisms — all of them", "ransom_alert", "Find every autorun, task, service, and WMI consumer.")],
            explanation="Ransomware is a persistence problem wearing an encryption costume."),
        "av_only": N("AV removed the payload binary but the scheduled task now fails loudly every hour and the registry Run key re-downloads it. Manual eradication was still required:",
            [C("Back up and do the full persistence sweep", "ransom_alert", "AV is a layer, not the whole eradication.")],
            explanation="Verify eradication; don't assume the scanner found every persistence trick."),
        "decryptor": N("The decryptor was for a different family — it corrupted the headers of 200 files. Test decryptors on COPIES, and only after identifying the family. The reliable path:",
            [C("Verified backup restore", "ransom_alert", "Backups don't care which ransomware family it is.")],
            explanation="Backups are family-agnostic. Decryptors aren't."),
        "giveup_data": N("The user mentions the 2 AM backup — which you never checked. The data was recoverable the whole time. Always:",
            [C("Check backups before declaring data lost", "ransom_alert", "The backup exists precisely for this sentence.")],
            explanation="'Files are gone' is a verdict you earn only after the backup check."),
        "restore": N("Files restored and verified; user working again by 5 PM. Last step — the one that makes the next incident cheaper:",
            [C("Write the incident report: timeline, entry point (phishing macro), dwell time, and add controls — attachment sandboxing, AppLocker, backup immutability", "end", "The report converts an incident into institutional immunity.")],
            explanation="Correct-path explanation: isolate → evidence → entry point → full eradication → verified restore → incident report with new controls. The report is what makes this the LAST time this vector works."),
        "end": N("Scenario complete. You ran a full IR lifecycle: 3-hour turnaround, data recovered, controls added. That's the drill the interview will ask about.",
            [C("Next scenario", "ransom_alert", "Try skipping the evidence step and feel the cost.")],
            explanation="Mastery = containment discipline + evidence hygiene + verified recovery + institutional learning."),
    })

branch("IL27-BRANCH-04", "IL27-M06", "Site-to-site VPN tunnel down",
    "vpn_down",
    {
        "vpn_down": N("8:02 AM: the branch office calls — they can't reach anything at HQ. The site-to-site VPN tunnel on pfSense shows DOWN. Your first diagnostic?",
            [C("Check whether it's the tunnel or the underlying internet on either side (ping each WAN, check gateway status)", "underlay", "Correct: VPNs die when the underlay dies. Rule out internet/path issues before touching crypto config."),
             C("Delete and rebuild the VPN tunnel from scratch", "rebuild", "Rebuilding a tunnel whose config was fine yesterday wastes an hour and risks new typos. Diagnose first."),
             C("Reboot both firewalls", "reboot_fw", "Rebooting firewalls drops ALL traffic at both sites for minutes — as step one it's pure hope."),
             C("Assume the branch ISP is down and wait", "wait", "Assumption without a single test. One ping disproves or confirms it in seconds.")]),
        "underlay": N("Both WANs are up; gateways respond; each firewall reaches the internet. The underlay is fine — the tunnel itself won't establish. Next?",
            [C("Check the IPsec logs on both sides for phase 1 / phase 2 errors", "logs", "Right: the logs name the failing phase. Phase 1 = authentication/peer; phase 2 = selectors/proposals."),
             C("Change the pre-shared key on both sides", "psk", "If the key were wrong it would never have worked — it worked yesterday. Don't churn what isn't broken."),
             C("Switch from IKEv2 to IKEv1 to 'simplify'", "downgrade", "Downgrading crypto to dodge a config issue weakens security for zero diagnostic gain.")]),
        "logs": N("HQ log: 'no matching proposal found' during phase 2. Branch recently updated their firewall firmware last night. Diagnosis?",
            [C("The firmware update reset/changed the phase 2 proposals — compare both sides' encryption/hash/DH settings and align them", "align", "Correct: 'no matching proposal' after a firmware update = the update changed defaults. Align the crypto maps."),
             C("The tunnel is being attacked — block the branch IP", "attack", "It's your own branch office failing negotiation, not an attacker. Read the log literally."),
             C("Increase the tunnel MTU", "mtu", "MTU issues cause black-holed traffic AFTER establishment, not proposal failures during negotiation.")],
            explanation="Correct path: verify underlay → read IPsec logs → identify the phase → align proposals after the firmware change. Most 'tunnel down' incidents are config drift, not crypto failure."),
        "align": N("Proposals aligned (AES-256/GCM, SHA256, DH14 both sides) — tunnel is UP, branch traffic flowing. Prevent the sequel:",
            [C("Document the exact crypto settings in the runbook and add a firmware-update checklist item: 'verify VPN proposals post-update'", "end", "Config drift is the enemy; the runbook is the weapon. The checklist item costs nothing and prevents the repeat.")],
            explanation="Correct-path explanation: underlay check → log-driven phase identification → proposal alignment after firmware drift → runbook + checklist. Thirty minutes, one permanent checklist item."),
        "rebuild": N("An hour into the rebuild you find a typo in the new PSK — and the original tunnel config (which was fine) is gone. Meanwhile the branch is still down. The lesson:",
            [C("Export/backup firewall configs before touching them; diagnose first", "vpn_down", "Rebuilds without backups turn one problem into two.")],
            explanation="Never rebuild crypto config without a backup of the working version."),
        "reboot_fw": N("Both firewalls rebooted: 6 minutes of total outage at both sites, tunnel still down (it was a proposal mismatch). Reboots don't fix:",
            [C("Configuration drift — back to the logs", "vpn_down", "Reboots fix stuck processes, not mismatched settings.")],
            explanation="If it worked yesterday and nothing rebooted it into failure, the cause is config or peer-side change."),
        "wait": N("Two hours later the branch manager calls your boss. A 30-second ping test at 8:03 would have shown the underlay was fine. Never:",
            [C("Substitute waiting for testing — restart with the underlay check", "vpn_down", "Hope is not a diagnostic step.")],
            explanation="Every minute of assumption is a minute the business is down."),
        "psk": N("New PSK on both sides — tunnel still down, and now you've introduced a change to chase. The log said 'no matching proposal' — that's phase 2 selectors, not authentication. Read the:",
            [C("Logs literally, then align proposals", "vpn_down", "The log told you the answer. Trust it.")],
            explanation="Match the fix to the logged error, not to a hunch."),
        "downgrade": N("IKEv1 'worked' — by weakening the negotiation. Security review flags it next week and you redo the whole thing properly. The right fix was always:",
            [C("Aligning the IKEv2 proposals", "vpn_down", "Never trade security for convenience in a diagnostic shortcut.")],
            explanation="Downgrading crypto to avoid diagnosis creates a finding you'll have to remediate anyway."),
        "attack": N("You blocked your own branch office IP. Now even the fixed tunnel can't reach HQ. Unblock it and read logs as written:",
            [C("It's a proposal mismatch with your own peer — restart", "vpn_down", "Know your peers before you block them.")],
            explanation="Blocking first and reading later turns incidents into self-inflicted outages."),
        "mtu": N("MTU changes did nothing — the tunnel never got past phase 2. MTU matters after establishment. Go back to the:",
            [C("Phase 2 proposal alignment", "vpn_down", "Fix the phase that's actually failing.")],
            explanation="Diagnose the failing phase; fix that phase."),
        "end": N("Scenario complete. Branch back online in ~30 minutes with a runbook update. VPN incidents are config-drift incidents wearing a crypto costume.",
            [C("Next scenario", "vpn_down", "Try the rebuild-first path and feel the hour evaporate.")],
            explanation="Mastery = underlay first, logs over hunches, align don't rebuild, checklist the drift."),
    })

branch("IL27-BRANCH-05", "IL27-M12", "File server out of disk at 2 AM",
    "disk_full",
    {
        "disk_full": N("2:07 AM: your phone buzzes — Zabbix: 'LAB-FS01 D: 98% full.' The file server's data volume is nearly full. Shares will freeze when it hits 100%. First move?",
            [C("Check what's consuming the space before deleting anything", "assess", "Correct: at 2 AM, deleting blind risks destroying the wrong data. Assess first — it takes minutes."),
             C("Delete the biggest files immediately to buy headroom", "delete_big", "The biggest files might be the finance share. 'Biggest first' without identification is how you delete the business."),
             C("Extend the virtual disk right now", "extend", "Extending buys space but if a runaway process is writing (logs, loop), you'll fill the new space too — and you haven't found the cause."),
             C("Ignore it until morning", "ignore", "At 98% with active writes, morning might be 100% with frozen shares and a crashed backup. 2 AM pages exist for this.")]),
        "assess": N("D:\\Shares is 380 GB of 400 GB. Breakdown: Departments 180 GB (normal), plus D:\\Shares\\Temp\\video-renders at 190 GB — someone's been dumping 4K video renders to the share for weeks. Action?",
            [C("Confirm with the owner, move renders to proper storage (or quota them), compress/clean temp, then set quotas + alerting", "fix_right", "Correct: the data isn't yours to delete unilaterally — confirm, relocate, then prevent with quotas and earlier alerts."),
             C("Delete the video-renders folder now", "delete_renders", "It's 2 AM and you haven't confirmed what it is. If it's the marketing team's active project, you just became the incident."),
             C("Just extend the disk to 800 GB and go back to sleep", "extend_sleep", "You'll be paged again in six weeks with the same folder at 700 GB. Extension without policy is a snooze button.")]),
        "fix_right": N("Owner confirms: renders are done, safe to archive. You move 190 GB to the archive NAS, D: drops to 48%. Now make 2 AM pages rarer:",
            [C("Set FSRM quotas on the shares (e.g. Temp capped at 50 GB), Zabbix trigger at 80% warning / 90% high, and a monthly storage review", "end", "The full fix: immediate relief + technical prevention (quotas) + earlier alerting + process (review)."),
             C("Nothing — it's fixed", "nothing", "Without quotas and earlier alerts, this exact page recurs. 'Fixed' without prevention is temporary.")],
            explanation="Correct path: assess before acting → identify the real consumer → confirm ownership → relocate → quotas + tiered alerting + review cadence. The 2 AM page becomes a 10 AM warning next time."),
        "delete_big": N("You deleted the 190 GB — it WAS the marketing team's active project, mid-campaign. Restore from backup took 3 hours and the CMO knows your name. Next time:",
            [C("Assess and confirm ownership before deleting anything", "disk_full", "Data has owners. Deletion is a confirmed, approved act.")],
            explanation="Never delete unilaterally at 2 AM. Identify, confirm, then act."),
        "extend": N("Disk extended to 800 GB. The render-dumping continues — you're paged again in 5 weeks at 98% of 800 GB, and the backup window no longer fits. The missing piece was:",
            [C("Finding the consumer and setting quotas", "disk_full", "Capacity without policy is just a bigger cliff.")],
            explanation="Extension treats the symptom. Quotas treat the behavior."),
        "ignore": N("6:30 AM: D: hit 100%. Shares froze mid-save, the backup failed, and three users lost work. The page at 2 AM was the cheap version of this incident:",
            [C("Respond to disk pages promptly — restart the scenario", "disk_full", "98% at 2 AM never gets better by morning.")],
            explanation="Disk-full pages are time bombs with visible timers. Defuse them."),
        "delete_renders": N("Deleted at 2 AM, no confirmation. It was active project data. The restore worked, but trust didn't. The rule:",
            [C("Confirm ownership — data deletion needs a name attached", "disk_full", "'Probably safe' is not an authorization.")],
            explanation="If you can't name the owner who approved deletion, don't delete."),
        "extend_sleep": N("Six weeks later: paged again, 98% of 800 GB, backup window blown. The snooze button worked exactly once. Permanent fix:",
            [C("Quotas + 80% early warning + ownership", "disk_full", "Policy beats capacity, every time.")],
            explanation="Every extension without policy just reschedules the page."),
        "nothing": N("Four months later the renders are back and so is the page. Prevention is part of the fix:",
            [C("Add the quotas and alerts now", "disk_full", "An incident without prevention is a rehearsal.")],
            explanation="Close the loop or repeat the incident."),
        "end": N("Scenario complete. A 2 AM page handled with discipline: assessed, confirmed, relocated, quota'd, alerted earlier. The next one pages at 80% during business hours.",
            [C("Next scenario", "disk_full", "Try deleting first and meet the CMO.")],
            explanation="Mastery = assess → confirm → relieve → prevent (quotas + tiered alerts + review)."),
    })

branch("IL27-BRANCH-06", "IL27-M16", "New-hire onboarding day",
    "onboard",
    {
        "onboard": N("Monday 8 AM: three new IT hires start. Your onboarding checklist is ready. Where do you begin?",
            [C("Create the AD accounts first (identity before everything)", "identity", "Correct: every other step — groups, mailbox, laptop login — depends on the identity existing."),
             C("Hand them laptops first so they can 'get settled'", "laptops_first", "Laptops without accounts are expensive paperweights — they can't log in, and you'll redo the setup."),
             C("Start with the HR paperwork and security briefing", "paperwork", "Important, but the accounts take provisioning time — start the technical chain first, do paperwork in parallel."),
             C("Give them all Domain Admin 'temporarily' to avoid access tickets", "domain_admin", "Never. 'Temporary' Domain Admin is how breaches start. Least privilege from minute one.")]),
        "identity": N("Accounts created in OU=Users via script, temp passwords set, change-at-logon flagged. Next: access. The hires need file shares, the ticketing system, and VPN. How?",
            [C("Add to role groups (LAB-IT etc.) per the access matrix; file/ticket/VPN access flows from group membership; elevated needs go through access-request tickets", "least_priv", "Correct: role-based access, documented, no standing privilege. This is the answer the interview wants to hear."),
             C("Clone the access of a senior admin 'to be safe'", "clone", "Cloning accumulates privilege nobody reviews — it's how 'temporary' access becomes permanent."),
             C("Ask each hire what they think they need and grant it", "ask_hire", "New hires don't know the access model on day one — that's YOUR job, via the matrix.")]),
        "least_priv": N("Access provisioned via groups. Laptops: joined to lab.local, baseline GPOs applied (gpresult confirms), Defender on, BitLocker encrypting. Now the human layer:",
            [C("Acceptable-use signature, phishing briefing, MFA enrollment — logged per hire with date/time", "human_layer", "Correct: the technical controls are half the onboarding; the human controls are the other half, and auditors check both."),
             C("Skip the briefing — they're IT, they know security", "skip_brief", "'They're IT' is how IT gets phished. Everyone gets the briefing; it's also your audit evidence."),
             C("Do the briefing 'later this week' when things calm down", "later", "Later never comes, and the highest-risk window is the first 72 hours with fresh credentials.")]),
        "human_layer": N("All three hires are productive by lunch: accounts, access, hardened laptops, briefings logged. One last onboarding discipline — the offboarding rehearsal:",
            [C("Create a test account, disable (not delete) it, verify auth fails and the audit log records it — proving your offboarding actually works", "end", "Elite move: most orgs never test offboarding until a real termination exposes the gaps. You just proved yours works on day one.")],
            explanation="Correct path: identity first → role-based least-privilege access → hardened devices → human-layer controls logged → offboarding rehearsal. Onboarding isn't 'accounts created' — it's 'productive, secure, and auditable by lunch.'"),
        "laptops_first": N("It's 10 AM: three people with laptops they can't log into, and you're now creating accounts under time pressure — mistakes love hurry. The right order was:",
            [C("Identity first — restart the morning", "onboard", "Dependencies order themselves: identity → access → device → human.")],
            explanation="Onboarding has a dependency chain. Start at the root: identity."),
        "paperwork": N("Paperwork done by 9:30, but accounts are still provisioning and laptops sit idle. Parallelize: technical chain first, paperwork alongside. Restart:",
            [C("Kick off account creation at 8:00 sharp", "onboard", "Lead with the long pole — provisioning — and fill the wait with paperwork.")],
            explanation="Start the slowest step first. Everything else fills the gaps."),
        "domain_admin": N("Week three: one 'temporary' Domain Admin account is used to 'fix' a GPO — badly — and the audit flags all three. 'Temporary' privilege is permanent risk. The policy:",
            [C("Least privilege from minute one; elevation via ticketed, time-bound process", "onboard", "There's no safe amount of standing Domain Admin for a new hire.")],
            explanation="Temporary elevated access is the most common privilege-creep vector in IT."),
        "clone": N("Six months later nobody can explain why the hires have backup-operator rights on the finance server. Cloned access is unreviewed access. Use:",
            [C("The role-based access matrix", "onboard", "Matrices get reviewed; clones get forgotten.")],
            explanation="Grant by role, not by copying a human."),
        "ask_hire": N("The hires requested (and got) local admin 'for drivers' — now one has a crypto miner. Access decisions belong to:",
            [C("The access matrix and their manager, not the new hire", "onboard", "Day-one hires can't assess their own risk footprint.")],
            explanation="Access is granted by role definition, not self-service."),
        "skip_brief": N("Month two: one of the three clicks a phishing link 'from IT.' The briefing you skipped was the control for exactly this. Everyone gets:",
            [C("The briefing on day one, logged", "onboard", "Phishing doesn't check job titles.")],
            explanation="Security awareness is per-human, not per-role."),
        "later": N("'Later this week' became never. The hires' first 72 hours — peak credential-theft risk — had no phishing briefing. Schedule it:",
            [C("Day one, before lunch", "onboard", "The riskiest window gets the control first.")],
            explanation="Controls delayed past the risk window are theater."),
        "end": N("Scenario complete. Three hires productive, secure, and auditable by lunch — plus a tested offboarding process. That's onboarding done right.",
            [C("Next scenario", "onboard", "Try the Domain Admin shortcut and watch month three.")],
            explanation="Mastery = dependency-ordered provisioning + least privilege + human controls + provable offboarding."),
    })

